def main():
    OUT.mkdir(parents=True, exist_ok=True)
    for old in OUT.glob("*.json"):
        old.unlink()
    index = []
    total = 0
    for t in TRACKS:
        assert len(t["lessons"]) in (3, 4, 5)
        for l in t["lessons"]:
            assert len(l["check"]) == 3, l["id"]
            assert l["learn_more"], l["id"]
            total += 1
        (OUT / f"{t['n']}-{t['id']}.json").write_text(json.dumps(t, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
        index.append({"id": t["id"], "file": f"{t['n']}-{t['id']}.json"})
    (OUT / "index.json").write_text(json.dumps({"tracks": index, "practice_case": "first-day"}, indent=1) + "\n", encoding="utf-8")
    print(f"{len(TRACKS)} tracks, {total} lessons -> {OUT}")

if __name__ == "__main__":
    main()
